@RealFounderWindow.nonempty_has_earliest : ∀ {birth : ℕ → ℝ},
  RealFounderWindow.StrictFiniteSublevels birth →
    ∀ (S : SpeciesBridge.NatSet), (∃ v, S v) → ∃ start, S start ∧ ∀ (v : ℕ), S v → birth start ≤ birth v

@RealFounderWindow.window_nonnegative : ∀ {E : SpeciesBridge.Graph} {birth : ℕ → ℝ},
  RealFounderWindow.Chronological E birth →
    ∀ {duration : ℝ} {S : SpeciesBridge.NatSet}, RealFounderWindow.Window E birth duration S → 0 ≤ duration
